#pragma once

#include <LovyanGFX.hpp>
#include <cstdint>

namespace desk::ui {

/// Raw VLW data, generated by tools/make_vlw.py.
namespace fontdata {
extern const std::uint8_t kGolos16Medium[];
extern const std::uint8_t kGolos12Regular[];
extern const std::uint8_t kGolos12Medium[];
extern const std::uint8_t kGolos34SemiBold[];
}  // namespace fontdata

/// Golos Text, anti-aliased, with Cyrillic. Each font is parsed once and then shared by
/// `setFont`, so switching fonts mid-frame costs nothing.
class Fonts {
 public:
  Fonts();
  Fonts(const Fonts&) = delete;
  Fonts& operator=(const Fonts&) = delete;

  const lgfx::IFont* name() const { return &name_.font; }      // 16 px medium: session names
  const lgfx::IFont* small() const { return &small_.font; }    // 12 px regular: details, times
  const lgfx::IFont* label() const { return &label_.font; }    // 12 px medium: header counts
  const lgfx::IFont* digits() const { return &digits_.font; }  // 34 px semibold: passkey

 private:
  struct Loaded {
    explicit Loaded(const std::uint8_t* data);
    lgfx::PointerWrapper source;
    lgfx::VLWfont font;
  };

  Loaded name_;
  Loaded small_;
  Loaded label_;
  Loaded digits_;
};

}  // namespace desk::ui
